std::optional<std::wstring> GetPwaAppIdForWindow(const Apps::AppData& app, HWND window) const;
static bool HasMatchingPwaIdentity(const std::wstring& savedPwaAppId,
                                   const std::optional<std::wstring>& observedPwaAppId)
{
    return savedPwaAppId.empty()
        ? !observedPwaAppId.has_value() || observedPwaAppId->empty()
        : observedPwaAppId.has_value() && savedPwaAppId == *observedPwaAppId;
}

auto PwaHelper::GetPwaAppIdForWindow(const Apps::AppData& app, HWND window) const
    -> std::optional<std::wstring>
{
    const auto aumid = Utils::GetAUMIDFromWindow(window);
    if (app.IsEdge()) return GetEdgeAppId(aumid);
    if (app.IsChrome()) return GetChromeAppId(aumid);
    return std::nullopt;
}
